    out=[r[:] for r in g]; H,W=len(g),len(g[0])
    painted=set()
    for i in range(H):
        j=0
        while j<W:
            if g[i][j]==8: j+=1; continue
            if g[i][j]==0 and j>0 and g[i][j-1]==8 and j<W-1 and g[i][j+1]==8:
                m=j
                while m<W and g[i][m]==0: m+=1
                n=j-1
                while n>=0 and g[i][n]==8: n-=1
                n_=m
                while n_+1<W and g[i][n_+1]==8: n_+=1
                lo,hi=n_,m-1
                for y in range(i-1,H):  # spray downward into adjacent corridor
                    for x in range(lo,hi+1):
                        if 0<=y<H and 0<=x<W and (g[y][x]==0 or g[y][x]==2):
                            painted.add((y,x))
                break
            j+=1
    for y,x in painted: out[y][x]=2
    return out
