def rects(g):
    H,W=len(g),len(g[0])
    gaps=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and j>0 and g[i][j-1]==8 and j<W-1 and g[i][j+1]==8: gaps.add((i,j))
    C8={(i,j) for i in range(H) for j in range(W) if g[i][j]==8}
    bg={(i,j) for i in range(H) for j in range(W) if g[i][j]==0}
    cand=[]
    for r1 in range(H):
        for c1 in range(W):
            for r2 in range(r1,H):
                for c2 in range(c1,W):
                    border=[(r1,c) for c in range(c1,c2+1)]+[(r2,c) for c in range(c1,c2+1)]+[(r,c1) for r in range(r1,r2+1)]+[(r,c2) for r in range(r1,r2+1)]
                    if all(g[x][y]==8 or (x,y) in gaps or (x,y) in bg for x,y in border):
                        nb=sum(1 for x,y in border if (x,y) in bg)
                        if nb>=1: cand.append((r1,c1,r2,c2,border,nb))
    return cand,gaps,bg,C8

