def comps_of(diff,I):
    seen=np.zeros_like(I,bool); out=[]
    for y,x in zip(*np.where(diff)):
        if not seen[y,x]:
            q=collections.deque([(int(y),int(x))]); seen[y,x]=True; comp=[(int(y),int(x))]
            while q:
                a,b=q.popleft()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
