                    if 0<=u<I.shape[0] and 0<=v<I.shape[1] and diff[u,v] and not seen[u,v]:
                        seen[u,v]=True; q.append((int(u),int(v))); comp.append((int(u),int(v)))
            out.append(comp)
    return out
